namespace DeskPins.App
{
    public sealed class ManagerWindow : Window
    {
        private readonly AppHost host;
        private readonly ListBox categories, notes;
        private readonly TreeView tree;
        private readonly TextBox search;
        private readonly ComboBox order;
        private readonly ContentControl preview;
        private readonly TextBlock count;
        private readonly DatePicker calendar;
        private readonly System.Windows.Threading.DispatcherTimer saveTimer;
        private TextEditor editor;
        private Note editing;
        private bool dirty, loading;
        private Grid body;
        private int lastCategory = -1;
        private string navigationSnapshot = "";
        private double navigationWidth = 170;
        private Point dragStart;
        private bool dragReady;
        private DateTime displayedModifiedUtc;
        private string folderFilter = "", stackFilter = "", tagFilter = "";
        private readonly string[] names = { "首页", "桌面", "堆叠", "附着", "休眠", "重复提醒", "日历", "已关闭", "已收藏", "标签", "搜索结果" };
        public ManagerWindow(AppHost host)
        {
            this.host = host; Title = "DeskPins · 管理便签"; Width = 1050; Height = 680; MinWidth = 780; MinHeight = 420; WindowStartupLocation = WindowStartupLocation.CenterScreen;
            Ui.FitDialog(this, 780, 420);
            saveTimer = new System.Windows.Threading.DispatcherTimer { Interval = TimeSpan.FromMilliseconds(600) }; saveTimer.Tick += (s, e) => SaveEditor();
            var root = new DockPanel(); var toolbar = new WrapPanel { Margin = new Thickness(7) }; DockPanel.SetDock(toolbar, Dock.Top); root.Children.Add(toolbar);
            toolbar.Children.Add(Ui.Button("新建", () => host.New())); toolbar.Children.Add(Ui.Button("恢复到桌面", () => Each(n => host.Library.Move(n, NoteState.Desktop)))); toolbar.Children.Add(Ui.Button("关闭", () => Each(n => host.Library.Move(n, NoteState.Closed)))); toolbar.Children.Add(Ui.Button("收藏", () => Each(n => host.Library.Move(n, NoteState.Stored)))); toolbar.Children.Add(Ui.Button("标签", () => host.AssignTags(Selected()))); toolbar.Children.Add(Ui.Button("文件夹…", () => host.Collections("folders"))); toolbar.Children.Add(Ui.Button("联系人…", () => host.Friends())); toolbar.Children.Add(Ui.Button("解锁 / 锁定", () => { if (host.Library.SessionPassword == null) { host.Unlock(); DisplaySelected(true); } else { SaveEditor(); host.Library.Lock(); editing = null; DisplaySelected(true); } })); toolbar.Children.Add(Ui.Button("设置…", () => host.Settings()));
            var bottom = new DockPanel { Margin = new Thickness(10, 4, 10, 8) }; DockPanel.SetDock(bottom, Dock.Bottom); root.Children.Add(bottom); bottom.Children.Add(new TextBlock { Text = "查找：", VerticalAlignment = VerticalAlignment.Center }); search = new TextBox { MinWidth = 250, Padding = new Thickness(5), VerticalContentAlignment = VerticalAlignment.Center }; search.KeyDown += (s, e) => { if (e.Key == Key.Enter) { categories.SelectedIndex = 10; Refresh(); } if (e.Key == Key.Escape) { search.Clear(); categories.SelectedIndex = 1; } }; bottom.Children.Add(Ui.Button("搜索", () => { categories.SelectedIndex = 10; Refresh(); })); bottom.Children.Add(search);
            body = new Grid(); body.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(110) }); body.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(170) }); body.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(5) }); body.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star), MinWidth = 230 }); body.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(5) }); body.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1.2, GridUnitType.Star), MinWidth = 220 }); root.Children.Add(body);
            for (int column = 2; column <= 4; column += 2) { var splitter = new GridSplitter { HorizontalAlignment = HorizontalAlignment.Stretch, VerticalAlignment = VerticalAlignment.Stretch, Width = 5, Background = System.Windows.Media.Brushes.Gainsboro, ResizeDirection = GridResizeDirection.Columns, ResizeBehavior = GridResizeBehavior.PreviousAndNext }; Grid.SetColumn(splitter, column); body.Children.Add(splitter); }
            categories = new ListBox { ItemsSource = names, BorderThickness = new Thickness(0), FontSize = 14, Padding = new Thickness(4) }; categories.SelectionChanged += (s, e) => { folderFilter = stackFilter = tagFilter = ""; BuildTree(); Refresh(); }; categories.AllowDrop = true; categories.Drop += (s, e) => { var target = FindItem(e.OriginalSource as DependencyObject); int i = target == null ? -1 : Array.IndexOf(names, target.Content as string); if (i == 1 || i == 7 || i == 8) { DropTo(e, i == 1 ? NoteState.Desktop : i == 7 ? NoteState.Closed : NoteState.Stored, ""); } }; body.Children.Add(categories);
            var navigation = new DockPanel { Margin = new Thickness(4) }; Grid.SetColumn(navigation, 1); body.Children.Add(navigation); calendar = new DatePicker { SelectedDate = DateTime.Today, Margin = new Thickness(2, 4, 2, 8) }; calendar.SelectedDateChanged += (s, e) => Refresh(); DockPanel.SetDock(calendar, Dock.Top); navigation.Children.Add(calendar); tree = new TreeView { BorderThickness = new Thickness(0) }; tree.SelectedItemChanged += (s, e) => { var selected = tree.SelectedItem as TreeViewItem; if (selected?.Tag is Folder) folderFilter = ((Folder)selected.Tag).Id; else if (selected?.Tag is NoteStack) stackFilter = ((NoteStack)selected.Tag).Id; else if (selected?.Tag is Tag) tagFilter = ((Tag)selected.Tag).Id; Refresh(); }; navigation.Children.Add(tree);
            var listing = new DockPanel { Margin = new Thickness(4) }; Grid.SetColumn(listing, 3); body.Children.Add(listing); var listHeader = new DockPanel { Margin = new Thickness(2, 2, 2, 7) }; DockPanel.SetDock(listHeader, Dock.Top); listing.Children.Add(listHeader); count = new TextBlock { VerticalAlignment = VerticalAlignment.Center }; order = new ComboBox { ItemsSource = new[] { "修改时间 ↓", "创建时间 ↓", "标题 A–Z", "提醒时间 ↑" }, SelectedIndex = 0, Width = 120, HorizontalAlignment = HorizontalAlignment.Right }; order.SelectionChanged += (s, e) => Refresh(); DockPanel.SetDock(order, Dock.Right); listHeader.Children.Add(order); listHeader.Children.Add(count);
            notes = new ListBox { SelectionMode = SelectionMode.Extended, BorderThickness = new Thickness(1) }; var template = new DataTemplate(typeof(Note)); var row = new FrameworkElementFactory(typeof(StackPanel)); row.SetValue(StackPanel.MarginProperty, new Thickness(5, 5, 5, 8)); var titleBlock = new FrameworkElementFactory(typeof(TextBlock)); titleBlock.SetBinding(TextBlock.TextProperty, new System.Windows.Data.Binding("DisplayTitle")); titleBlock.SetValue(TextBlock.FontWeightProperty, FontWeights.SemiBold); titleBlock.SetValue(TextBlock.TextTrimmingProperty, TextTrimming.CharacterEllipsis); titleBlock.SetBinding(TextBlock.ToolTipProperty, new System.Windows.Data.Binding("DisplayTitle")); row.AppendChild(titleBlock); var dateBlock = new FrameworkElementFactory(typeof(TextBlock)); dateBlock.SetBinding(TextBlock.TextProperty, new System.Windows.Data.Binding("DateLabel")); dateBlock.SetValue(TextBlock.ForegroundProperty, System.Windows.Media.Brushes.SteelBlue); row.AppendChild(dateBlock); var summary = new FrameworkElementFactory(typeof(TextBlock)); summary.SetBinding(TextBlock.TextProperty, new System.Windows.Data.Binding("DisplayPreview")); summary.SetValue(TextBlock.MaxWidthProperty, 280d); summary.SetValue(TextBlock.TextTrimmingProperty, TextTrimming.CharacterEllipsis); row.AppendChild(summary); template.VisualTree = row; notes.ItemTemplate = template; notes.SelectionChanged += (s, e) => DisplaySelected(); notes.MouseDoubleClick += (s, e) => { var n = notes.SelectedItem as Note; if (n == null) return; if (n.Attachment != null && !host.IsAttachmentVisible(n)) new AttachWindow(host, n).ShowDialog(); else if (n.State == NoteState.Desktop) host.Focus(n); else if (n.State == NoteState.Sleeping || n.State == NoteState.Recurring) new ScheduleWindow(host, n, true, n.State == NoteState.Recurring).ShowDialog(); else if (n.Attachment != null) new AttachWindow(host, n).ShowDialog(); else { host.Library.Move(n, NoteState.Desktop); host.Focus(n); } };
            notes.PreviewMouseLeftButtonDown += (s, e) => { dragReady = FindItem(e.OriginalSource as DependencyObject) != null; dragStart = e.GetPosition(notes); };
            notes.PreviewMouseLeftButtonUp += (s, e) => dragReady = false;
            notes.PreviewMouseMove += (s, e) => { var p = e.GetPosition(notes); if (dragReady && e.LeftButton == MouseButtonState.Pressed && (Math.Abs(p.X - dragStart.X) >= SystemParameters.MinimumHorizontalDragDistance || Math.Abs(p.Y - dragStart.Y) >= SystemParameters.MinimumVerticalDragDistance) && Selected().Length > 0) { dragReady = false; DragDrop.DoDragDrop(notes, new DataObject("DeskPins.Notes", Selected().Select(n => n.Id).ToArray()), DragDropEffects.Move); } }; notes.ContextMenu = Context(); listing.Children.Add(notes);
            notes.SetValue(ScrollViewer.HorizontalScrollBarVisibilityProperty, ScrollBarVisibility.Disabled); notes.HorizontalContentAlignment = HorizontalAlignment.Stretch;
            preview = new ContentControl { Margin = new Thickness(8), BorderThickness = new Thickness(0), HorizontalContentAlignment = HorizontalAlignment.Stretch, VerticalContentAlignment = VerticalAlignment.Stretch }; Grid.SetColumn(preview, 5); body.Children.Add(preview); Content = root;
            host.Library.Changed += Changed; Closing += (s, e) => { try { SaveEditor(); host.Library.SaveCatalog(); } catch (Exception ex) { e.Cancel = true; Ui.Error(ex); } }; Closed += (s, e) => { saveTimer.Stop(); host.Library.Changed -= Changed; }; Deactivated += (s, e) => SaveEditor(); PreviewKeyDown += (s, e) => { if (e.Key == Key.F2) { var n = notes.SelectedItem as Note; if (n != null) { var title = Ui.Ask("设置标题", "标题", n.Title); if (title != null) { n.Title = title; host.Library.Save(n); } } e.Handled = true; } if (e.Key == Key.F && Keyboard.Modifiers == ModifierKeys.Control) { search.Focus(); e.Handled = true; } }; categories.SelectedIndex = 0; BuildTree(); Refresh();
        }
        private void Changed() { Dispatcher.BeginInvoke(new Action(Refresh), System.Windows.Threading.DispatcherPriority.Background); }
        public void Refresh()
        {
            if (notes == null || order == null || categories == null) return; string selected = (notes.SelectedItem as Note)?.Id; IEnumerable<Note> list = host.Library.Notes.Values; int category = categories.SelectedIndex;
            BuildTree();
            if (lastCategory != category) { lastCategory = category; int saved; host.Library.Catalog.Settings.ManagerOrders.TryGetValue(category, out saved); order.SelectedIndex = Math.Max(0, Math.Min(3, saved)); }
            else host.Library.Catalog.Settings.ManagerOrders[category] = order.SelectedIndex;
            bool showNavigation = category == 2 || category == 8 || category == 9 || category == 6;
            if (body.ColumnDefinitions[1].Width.Value > 0) navigationWidth = body.ColumnDefinitions[1].Width.Value;
            body.ColumnDefinitions[1].Width = new GridLength(showNavigation ? navigationWidth : 0);
            body.ColumnDefinitions[2].Width = new GridLength(showNavigation ? 5 : 0);
            foreach (var splitter in body.Children.OfType<GridSplitter>().Where(s => Grid.GetColumn(s) == 2)) splitter.Visibility = showNavigation ? Visibility.Visible : Visibility.Collapsed;
            foreach (var note in host.Library.Notes.Values) { note.DisplayModifiedDates = host.Library.Catalog.Settings.ManagerModifiedDates; note.CompactPreview = host.Library.Catalog.Settings.CompactList; }
            switch (category) { case 1: list = list.Where(n => n.State == NoteState.Desktop && n.StackId == "" && (n.Attachment == null || host.IsAttachmentVisible(n))); break; case 2: list = list.Where(n => n.StackId != "" && (stackFilter == "" || n.StackId == stackFilter)); break; case 3: list = list.Where(n => n.Attachment != null && !host.IsAttachmentVisible(n)); break; case 4: list = list.Where(n => n.State == NoteState.Sleeping); break; case 5: list = list.Where(n => n.State == NoteState.Recurring); break; case 6: var date = calendar.SelectedDate ?? DateTime.Today; list = list.Where(n => n.CreatedUtc.ToLocalTime().Date == date.Date || (n.WakeUtc.HasValue && n.WakeUtc.Value.ToLocalTime().Date == date.Date) || (n.Repeat != null && RepeatSchedule.Next(n.Repeat, date.Date.AddTicks(-1))?.Date == date.Date)); break; case 7: list = list.Where(n => n.State == NoteState.Closed); break; case 8: list = list.Where(n => n.State == NoteState.Stored && (folderFilter == "" || n.FolderId == folderFilter)); break; case 9: list = list.Where(n => tagFilter == "" ? n.Tags.Count > 0 : n.Tags.Contains(tagFilter)); break; case 10: list = host.Library.Search(search.Text); break; }
            if (order.SelectedIndex == 2) list = list.OrderBy(n => n.DisplayTitle); else if (order.SelectedIndex == 1) list = list.OrderByDescending(n => n.CreatedUtc); else if (order.SelectedIndex == 3) list = list.OrderBy(n => n.WakeUtc ?? n.AlarmUtc ?? DateTime.MaxValue); else list = list.OrderByDescending(n => n.ModifiedUtc);
            var items = list.ToList(); loading = true; notes.ItemsSource = items; notes.SelectedItem = items.FirstOrDefault(n => n.Id == selected); loading = false; count.Text = items.Count + " 张便签"; calendar.Visibility = category == 6 ? Visibility.Visible : Visibility.Collapsed; tree.Visibility = category == 2 || category == 8 || category == 9 ? Visibility.Visible : Visibility.Collapsed; DisplaySelected();
            if (category == 0 && notes.SelectedItem == null) preview.Content = new TextBlock { Text = "DeskPins · 桌钉\n\n" + string.Join("\n", Enum.GetValues(typeof(NoteState)).Cast<NoteState>().Select(state => state + "：" + host.Library.Notes.Values.Count(n => n.State == state))) + "\n\n双击桌面便签即可定位，关闭的便签可恢复。", FontSize = 16, Margin = new Thickness(15) };
        }
        private void DisplaySelected(bool force = false)
        {
            if (loading) return; var n = notes.SelectedItem as Note; if (!force && ReferenceEquals(editing, n) && (n == null || dirty || n.ModifiedUtc == displayedModifiedUtc)) return; SaveEditor(); editing = n; editor = null; dirty = false; preview.Content = null; if (n == null) return;
            displayedModifiedUtc = n.ModifiedUtc;
            if (n.Encrypted && host.Library.SessionPassword == null) { preview.Content = new StackPanel { Children = { new TextBlock { Text = "此便签已加密", FontSize = 18, Margin = new Thickness(10) }, Ui.Button("解锁", () => { host.Unlock(); DisplaySelected(true); }) } }; return; }
            try
            {
                host.Library.Load(n); loading = true; var panel = new DockPanel(); var title = new TextBlock { Text = n.DisplayTitle, FontSize = 17, FontWeight = FontWeights.SemiBold, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(2, 4, 2, 10) }; DockPanel.SetDock(title, Dock.Top); panel.Children.Add(title); var info = new TextBlock { Text = n.State + " · " + n.ModifiedUtc.ToLocalTime().ToString("yyyy-MM-dd HH:mm") + "\n" + string.Join(" / ", n.Tags.Select(id => host.Library.Catalog.Tags.FirstOrDefault(t => t.Id == id)?.Name ?? id)), Foreground = System.Windows.Media.Brushes.Gray, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(2, 3, 2, 8) }; DockPanel.SetDock(info, Dock.Bottom); panel.Children.Add(info);
                if (n.Kind == NoteKind.Text) { editor = new TextEditor(); editor.Read(n); editor.Background = Ui.Brush(n.Color); editor.TextChanged += (s, e) => { if (!loading) { dirty = true; saveTimer.Stop(); saveTimer.Start(); } }; panel.Children.Add(editor); } else { var image = new ImageEditor { Locked = true }; image.Read(n.Body); panel.Children.Add(new ScrollViewer { Content = image, HorizontalScrollBarVisibility = ScrollBarVisibility.Auto, VerticalScrollBarVisibility = ScrollBarVisibility.Auto }); }
                preview.Content = panel; loading = false;
            }
            catch (Exception ex) { loading = false; preview.Content = new TextBlock { Text = ex.Message, TextWrapping = TextWrapping.Wrap }; }
        }
        public void FlushPending(Note note = null) { if (note == null || editing?.Id == note.Id) SaveEditor(); }
        private void SaveEditor() { saveTimer.Stop(); if (!dirty || editing == null || editor == null || !host.Library.Notes.ContainsKey(editing.Id)) return; editor.Write(editing); host.Library.Save(editing); dirty = false; displayedModifiedUtc = editing.ModifiedUtc; host.ReloadWindow(editing); }
        private Note[] Selected() { return notes.SelectedItems.Cast<Note>().ToArray(); }
        private void Each(Action<Note> action) { SaveEditor(); try { foreach (var n in Selected()) action(n); Refresh(); } catch (Exception ex) { Ui.Error(ex); } }
        private ContextMenu Context() { var m = new ContextMenu(); m.Items.Add(Ui.Item("恢复 / 唤醒", () => Each(n => host.Library.Move(n, NoteState.Desktop)))); m.Items.Add(Ui.Item("关闭", () => Each(n => host.Library.Move(n, NoteState.Closed)))); m.Items.Add(Ui.Item("收藏", () => Each(n => host.Library.Move(n, NoteState.Stored)))); m.Items.Add(Ui.Item("复制", () => Each(n => host.Library.Copy(n)))); m.Items.Add(Ui.Item("标签…", () => host.AssignTags(Selected()))); m.Items.Add(Ui.Item("Ghost 开启", () => Each(n => { n.Ghost = true; host.Library.Save(n); }))); m.Items.Add(Ui.Item("Ghost 关闭", () => Each(n => { n.Ghost = false; host.Library.Save(n); }))); m.Items.Add(Ui.Item("分离附着", () => Each(n => { n.Attachment = null; host.Library.Save(n); }))); m.Items.Add(Ui.Item("导出…", () => Each(host.Export))); m.Items.Add(Ui.Item("属性…", () => { var n = notes.SelectedItem as Note; if (n != null) MessageBox.Show(Json.Text(n), "便签属性"); })); m.Items.Add(Ui.Item("永久删除…", () => { if (Ui.Confirm("永久删除选中的便签？")) Each(host.Library.Delete); })); return m; }
        private void BuildTree()
        {
            var snapshot = categories.SelectedIndex + ":" + Json.Text(host.Library.Catalog.Folders.Select(f => new[] { f.Id, f.Name, f.ParentId, f.Encrypted.ToString() }).ToArray()) + Json.Text(host.Library.Catalog.Stacks.Select(s => new[] { s.Id, s.Name }).ToArray()) + Json.Text(host.Library.Catalog.Tags.Select(t => new[] { t.Id, t.Name }).ToArray());
            if (tree == null || snapshot == navigationSnapshot) return;
            navigationSnapshot = snapshot;
            if (!host.Library.Catalog.Folders.Any(f => f.Id == folderFilter)) folderFilter = ""; if (!host.Library.Catalog.Stacks.Any(s => s.Id == stackFilter)) stackFilter = ""; if (!host.Library.Catalog.Tags.Any(t => t.Id == tagFilter)) tagFilter = "";
            if (tree == null) return; tree.Items.Clear(); if (categories.SelectedIndex == 8) { var roots = host.Library.Catalog.Folders.Where(f => f.ParentId == "").ToArray(); foreach (var f in roots) tree.Items.Add(FolderNode(f, new HashSet<string>())); } else if (categories.SelectedIndex == 2) foreach (var s in host.Library.Catalog.Stacks) tree.Items.Add(new TreeViewItem { Header = s.Name, Tag = s }); else if (categories.SelectedIndex == 9) foreach (var t in host.Library.Catalog.Tags) tree.Items.Add(new TreeViewItem { Header = t.Name, Tag = t });
            foreach (var node in Nodes(tree.Items)) if ((node.Tag as Folder)?.Id == folderFilter || (node.Tag as NoteStack)?.Id == stackFilter || (node.Tag as Tag)?.Id == tagFilter) { node.IsSelected = true; break; }
        }
        private static IEnumerable<TreeViewItem> Nodes(ItemCollection items) { foreach (TreeViewItem item in items) { yield return item; foreach (var child in Nodes(item.Items)) yield return child; } }
        private TreeViewItem FolderNode(Folder f, HashSet<string> visited) { var node = new TreeViewItem { Header = (f.Encrypted ? "🔒 " : "") + f.Name, Tag = f, AllowDrop = true, IsExpanded = true }; if (!visited.Add(f.Id)) return node; foreach (var child in host.Library.Catalog.Folders.Where(x => x.ParentId == f.Id)) node.Items.Add(FolderNode(child, visited)); node.Drop += (s, e) => { if (e.Handled || !e.Data.GetDataPresent("DeskPins.Notes")) return; e.Handled = true; try { host.EnsureUnlocked(f); DropTo(e, NoteState.Stored, f.Id); } catch (Exception ex) { Ui.Error(ex); } }; return node; }
        private void DropTo(DragEventArgs e, NoteState state, string folder) { if (!e.Data.GetDataPresent("DeskPins.Notes")) return; e.Handled = true; try { SaveEditor(); var targets = ((string[])e.Data.GetData("DeskPins.Notes")).Where(host.Library.Notes.ContainsKey).Select(id => host.Library.Notes[id]).ToArray(); foreach (var n in targets) host.FlushNote(n); host.Library.Atomic(() => { foreach (var n in targets) host.Library.Move(n, state, folder); }); Refresh(); } catch (Exception ex) { Ui.Error(ex); } }
        private static ListBoxItem FindItem(DependencyObject obj) { while (obj != null && !(obj is ListBoxItem)) obj = obj is System.Windows.Media.Visual || obj is System.Windows.Media.Media3D.Visual3D ? System.Windows.Media.VisualTreeHelper.GetParent(obj) : LogicalTreeHelper.GetParent(obj); return obj as ListBoxItem; }
    }
}
